\label{lem:inf_conv}
For every $R \geq 0$,
\begin{equation}
    K_{\mathrm{DK}}(R) = \min_{0 \leq a \leq R}
    \big\{ K_{\mathrm{O}}(a) + (R - a) \big\}.
    \label{eq:inf_conv}
\end{equation}

\label{thm:KDK_KO}
    For every $R\ge0$, 
    \begin{equation}\label{eq:KDK_KO_criterion}
\begin{aligned}
& K_{\mathrm{DK}}(R)=K_{\mathrm{O}}(R) \\
\Longleftrightarrow\quad
& K_{\mathrm{O}}(R)
  \le  K_{\mathrm{O}}(a)+ R-a\quad\forall \,a\in [0,R].
\end{aligned}
\end{equation}

\label{lem:endpoint_line}
For every pair $(P,V)$,
\begin{equation}
    D(V \| W | P) - I(P,V) \geq - C_{\infty}(W),
    \label{eq:endpoint_bound}
\end{equation}
with equality if and only if $(P,V) \in \mathcal{M}$.

xpanding $I(P,V)$ and $D(V \| W | P)$, we get
\begin{align}
    &D(V \| W | P) - I(P,V)  \notag\\
      &\; =- H(PV) - \sum_{x,y} P(x) V(y|x) \log W(y|x).
    \label{eq:g_expression}
\end{align}
By the Gibbs inequality, $-H(PV) \geq \sum_{y} PV(y) \log Q^{\star}(y)$, with equality if and only if $PV = Q^{\star}$. Substituting into \eqref{eq:g_expression},
\begin{equation}
    D(V \| W | P) - I(P,V) \geq \sum_{x,y} P(x) V(y|x) \log \frac{Q^{\star}(y)}{W(y|x)}.
    \label{eq:step_gibbs}
\end{equation}
For every $(x,y)$ with $P(x)V(y|x) > 0$,
\begin{equation}
    \frac{Q^{\star}(y)}{W(y|x)} = \mathrm{e}^{-C_{\infty}(W)} \frac{\max_{x'} W(y|x')}{W(y|x)} \geq \mathrm{e}^{-C_{\infty}(W)},
    \label{eq:ratio_bound}
\end{equation}
with equality if and only if $y \in \mathcal{Y}_x$. Substituting \eqref{eq:ratio_bound} into \eqref{eq:step_gibbs} gives \eqref{eq:endpoint_bound}. Equality in \eqref{eq:endpoint_bound} holds if and only if $PV = Q^{\star}$ and equality holds in \eqref{eq:ratio_bound} for every $(x,y)$ with $P(x)V(y|x) > 0$, which is the definition of $\mathcal{M}$.

\label{lem:interval}
Viewed as a set of joint distributions $P\times V$, $\mathcal M$ is convex and compact.  Moreover, $\{ I(P,V) : (P,V) \in \mathcal{M} \}$ is equal to the interval $ [R_{\star}, R^{\star}]$, where 
\begin{equation}
    R_{\star} := \min_{(P,V) \in \mathcal{M}} I(P,V), \qquad
    R^{\star} := \max_{(P,V) \in \mathcal{M}} I(P,V).
    \label{eq:R_star_def}
\end{equation}
Finally, $C_{\infty}(W) \leq R_{\star} \leq R^{\star} \leq \min\{ \log|\mathcal{X}|, H(Q^{\star}) \}$.

\label{thm:main}
For every $R \geq 0$,
\begin{list}{}{\setlength{\leftmargin}{1.6em}\setlength{\labelwidth}{1.2em}\setlength{\labelsep}{0.4em}\setlength{\itemsep}{0pt}\setlength{\parsep}{0pt}\setlength{\topsep}{2pt}}
    \par\hangindent 40\p@[(a)] ${K_{\mathrm{DK}}(R) = K_{\infty}(R)}$ if and only if ${R \geq R_{\star}}$;
    \par\hangindent 40\p@[(b)] ${K_{\mathrm{O}}(R) = K_{\infty}(R)}$ if and only if ${R_{\star} \leq R \leq R^{\star}}$;
    \par\hangindent 40\p@[(c)] ${K_{\mathrm{O}}(R) = K_{\mathrm{DK}}(R)}$ if and only if ${R \leq R^{\star}}$.
\end{list}
Consequently, ${K_{\mathrm{O}}(R) > K_{\mathrm{DK}}(R) = K_{\infty}(R)}$ for ${R > R^{\star}}$.

e prove each statement separately.

\emph{Part (a).} Fix $(P,V)$. If $I(P,V) \leq R$, then by Lemma~\ref{lem:endpoint_line},
\begin{align*}
    & D(V \| W | P) + |R - I(P,V)|^{+} \\
    & = D(V \| W | P) - I(P,V) + R \geq K_{\infty}(R),
\end{align*}
with equality if and only if $(P,V) \in \mathcal{M}$. On the other hand, if $I(P,V) > R$, then by Lemma~\ref{lem:endpoint_line},
\begin{align*}
    & D(V \| W | P) + |R - I(P,V)|^{+} \\
    & = D(V \| W | P) \geq I(P,V) - C_{\infty}(W) > K_{\infty}(R).
\end{align*}
Minimizing over $(P,V)$ gives $K_{\mathrm{DK}}(R) \geq K_{\infty}(R)$, with equality if and only if $I(P,V) \leq R$ is satisfied by some $(P,V) \in \mathcal{M}$. By Lemma~\ref{lem:interval}, this holds if and only if $R \geq R_{\star}$.

\emph{Part (b).} Fix a pair $(P,V)$ with $I(P,V) \geq R$. By Lemma~\ref{lem:endpoint_line},
\begin{equation*}
    D(V \| W | P) \geq I(P,V) - C_{\infty}(W) \geq K_{\infty}(R),
\end{equation*}
with equality throughout if and only if $(P,V) \in \mathcal{M}$ and $I(P,V) = R$. Minimizing over such pairs gives $K_{\mathrm{O}}(R) \geq K_{\infty}(R)$, with equality if and only if some $(P,V) \in \mathcal{M}$ has $I(P,V) = R$, i.e., by Lemma~\ref{lem:interval}, if and only if $R \in [R_{\star}, R^{\star}]$.

\emph{Part (c).} For $R > R^{\star}$, parts (a) and (b) give $K_{\mathrm{DK}}(R) = K_{\infty}(R) < K_{\mathrm{O}}(R)$, proving the ``only if'' part of the statement. 

Now for the ``if'' part, let $R \leq R^{\star}$. It suffices to show $K_{\mathrm{O}}(R) \leq K_{\mathrm{DK}}(R)$. Let $(P_0,V_0)$ attain the minimum in \eqref{eq:dual_def}. If $I(P_0,V_0) \geq R$, then $(P_0,V_0)$ is feasible in the minimization defining $K_{\mathrm{O}}(R)$, and $K_{\mathrm{O}}(R) \leq D(V_0 \| W | P_0) = K_{\mathrm{DK}}(R)$. Otherwise, we have $I(P_0,V_0) < R$ and
\begin{equation}
    K_{\mathrm{DK}}(R) = D(V_0 \| W | P_0) - I(P_0,V_0) + R.
    \label{eq:K_DK_at_P0}
\end{equation}
By Lemma~\ref{lem:interval}, there is $(P_1,V_1) \in \mathcal{M}$ with $I(P_1,V_1) = R^{\star} \geq R$. For $t \in [0,1]$, let $(P_t,V_t)$ be the pair with
\begin{equation*}
    P_t \times V_t := (1-t) \, (P_0 \times V_0) + t \, (P_1 \times V_1) .
\end{equation*}
By continuity of $I(P_t,V_t)$ in $t$, there is $t \in (0,1]$ with $I(P_t,V_t) = R$. By convexity of $D(V \| W | P) - I(P,V)$ in $P \times V$ and Lemma~\ref{lem:endpoint_line},
\begin{align}
\nonumber
    & D(V_t \| W | P_t) - I(P_t,V_t) \\
\nonumber
    & \leq (1-t) \big( D(V_0 \| W | P_0) - I(P_0,V_0) \big) - t \, C_{\infty}(W) \\
    & \leq D(V_0 \| W | P_0) - I(P_0,V_0).
    \label{eq:segment_convexity}
\end{align}
Adding $I(P_t,V_t) = R$ to both sides and using \eqref{eq:K_DK_at_P0} gives $D(V_t \| W | P_t) \leq K_{\mathrm{DK}}(R)$. Since $(P_t,V_t)$ is feasible in the minimization defining $K_{\mathrm{O}}(R)$, then $K_{\mathrm{O}}(R) \leq K_{\mathrm{DK}}(R)$.

\label{cor:no_gap}
$K_{\mathrm{O}}(R) = K_{\mathrm{DK}}(R)$ for all $R \in [0,\log|\mathcal{X}|]$ if and only if there exists a maximum-likelihood map $\phi$, i.e., $W(y|\phi(y)) = \max_{x} W(y|x)$ for every $y$, such that 
\begin{equation}
    \sum_{y : \phi(y) = x} \max_{x'} W(y|x') = \frac{\mathrm{e}^{C_{\infty}(W)}}{|\mathcal{X}|}
    \label{eq:equal_mass}
\end{equation}
holds for every input $x \in \mathcal{X}$.
